@patch
def load_or_compute_chunk_watersheds(self: GeoStorage,
                                     cover: ChunkCover,
                                     coarse_basins: DrainageBasins,
                                     chunk: HexChunk,
                                     chunk_ref: ChunkRef,
                                     fine_regions: dict[int, set[int]],
                                     zoomed_terrain: Terrain,
                                     force_recompute: bool = False) -> LoadResult:
    """Load cached watershed assignments or compute using ChunkCover projection.
    
    WARNING: Must use cover.project_watersheds() to avoid O(n²) computation!
    
    Cache key: (cover_id, chunk_pos, scale)
    Invalidate when: coarse watersheds change
    """
    # 1. Check cache
    if not force_recompute:
        if self.has_chunk_watersheds(cover.ident, chunk_ref, min_count=chunk.core_size // 2):
            result = self.load_chunk_watersheds(cover.ident, chunk, chunk_ref)
            if result.status == 'loaded':
                return LoadResult(chunk, 'cached', result.context)
    
    # 2. Compute using ChunkCover's efficient projection
    # This uses the coarse flow patterns, NOT O(n²) recomputation
    zoomed_sheds = cover.project_watersheds(
        coarse_basins, 
        fine_regions, 
        zoomed_terrain
    )
    
    # 3. Assign watershed IDs to chunk hexes
    if 'watershed_id' not in chunk.fields:
        chunk.add_field('watershed_id', default=-1)
    
    for ws_id, watershed in enumerate(zoomed_sheds):
        for hex_idx in watershed.region.hexes:
            # Map from zoomed terrain index to chunk index
            world_pos = zoomed_terrain.hexGrid.index_to_hexposition(hex_idx)
            chunk_idx = chunk.world_to_index(world_pos)
            if chunk_idx >= 0:
                chunk.fields['watershed_id'][chunk_idx] = ws_id
    
    # 4. Save to cache
    save_result = self.save_chunk_watersheds(chunk, chunk_ref, cover.ident)
    
    return LoadResult(chunk, 'computed', save_result.context)


