@patch
def zoom_with_full_data(self: ChunkCover,
                        origin: int = None,
                        scale: int = 2,
                        compute_weather: bool = True,
                        compute_watersheds: bool = True,
                        force_regenerate: bool = False) -> Terrain:
    """Zoom chunk with weather and watersheds, using cache where possible."""
    if self.db is None:
        raise ValueError("ChunkCover.db must be set for caching")
    
    grid = self.terrain.hexGrid
    if origin is None:
        origin = grid.middle
    origin_pos = grid.index_to_hexposition(origin)
    
    # Step 1: Base terrain (cached)
    result = self.db.load_or_generate_chunk(
        self, origin=origin, scale=scale, force_regenerate=force_regenerate
    )
    zoomed = result.data
    
    # Step 2: Weather
    if compute_weather:
        if not force_regenerate and self.db.has_zoomed_weather(self.ident, origin_pos, scale):
            self.db.load_zoomed_weather(self.ident, origin_pos, scale, zoomed)
        else:
            zoomed.climate = self.terrain.climate
            zoomed.geo = self.terrain.geo
            zoomed.compute_weather()
            self.db.save_zoomed_weather(self.ident, origin_pos, scale, zoomed)
    
    # Step 3: Watersheds
    if compute_watersheds:
        if not force_regenerate and self.db.has_zoomed_watersheds(self.ident, origin_pos, scale):
            self.db.load_zoomed_watersheds(self.ident, origin_pos, scale, zoomed)
        else:
            coarse_basins = DrainageBasins(self.terrain)
            fine_regions = self._build_fine_regions_map(origin, scale, zoomed)
            zoomed.watersheds = self.project_watersheds(coarse_basins, fine_regions, zoomed)
            self.db.save_zoomed_watersheds(self.ident, origin_pos, scale, zoomed, zoomed.watersheds)
    
    return zoomed


